/**
 * Error classes emulating the Python exception types that the original
 * test4.py program can raise, plus the control-flow exceptions used by the
 * argparse and construct emulations.
 *
 * Python equivalents:
 *   PyValueError        -> builtins.ValueError
 *   PyTypeError         -> builtins.TypeError
 *   PyAttributeError    -> builtins.AttributeError
 *   PyOSError           -> builtins.OSError (and BrokenPipeError subclass)
 *   ArgumentTypeError   -> argparse.ArgumentTypeError
 *   ArgumentError       -> argparse.ArgumentError ("argument --a: <message>")
 *   ArgumentParserExit  -> SystemExit raised by ArgumentParser.exit()
 *   ConstructError      -> construct.ConstructError
 *   StreamError         -> construct.StreamError
 */

/** Base class for every emulated Python exception. */
export class PyException extends Error {
  /**
   * @param {string} message text after the "ClassName: " prefix
   * @param {string} pyName the Python class name used when rendering tracebacks
   */
  constructor(message, pyName) {
    super(message);
    this.name = pyName;
    // Name used by traceback.mjs for the final "ClassName: message" line.
    this.pyName = pyName;
  }
}

/** builtins.ValueError */
export class PyValueError extends PyException {
  constructor(message) {
    super(message, 'ValueError');
  }
}

/** builtins.TypeError */
export class PyTypeError extends PyException {
  constructor(message) {
    super(message, 'TypeError');
  }
}

/** builtins.AttributeError */
export class PyAttributeError extends PyException {
  constructor(message) {
    super(message, 'AttributeError');
  }
}

/** builtins.OSError; `errnoName` allows BrokenPipeError-style subclasses. */
export class PyOSError extends PyException {
  constructor(message, pyName = 'OSError') {
    super(message, pyName);
  }
}

/** argparse.ArgumentTypeError - raised by custom `type=` callables. */
export class ArgumentTypeError extends PyException {
  constructor(message) {
    super(message, 'ArgumentTypeError');
  }
}

/**
 * argparse.ArgumentError - carries the offending action so that str(err)
 * renders as "argument -h/--help: <message>".
 */
export class ArgumentError extends PyException {
  /**
   * @param {{optionStrings?: string[], dest?: string, metavar?: string}|null} action
   * @param {string} message
   */
  constructor(action, message) {
    super(message, 'ArgumentError');
    this.argumentName = getActionName(action);
    this.rawMessage = message;
  }

  /** Mirrors argparse.ArgumentError.__str__. */
  toString() {
    if (this.argumentName === null) return this.rawMessage;
    return `argument ${this.argumentName}: ${this.rawMessage}`;
  }
}

/**
 * argparse._get_action_name: option actions are named by joining every option
 * string with '/', e.g. "-h/--help"; positionals fall back to metavar/dest.
 * @param {{optionStrings?: string[], dest?: string, metavar?: string}|null} action
 * @returns {string|null}
 */
export function getActionName(action) {
  if (action === null || action === undefined) return null;
  if (action.optionStrings && action.optionStrings.length > 0) {
    return action.optionStrings.join('/');
  }
  if (action.metavar !== undefined && action.metavar !== null) return action.metavar;
  if (action.dest !== undefined && action.dest !== null && action.dest !== '==SUPPRESS==') {
    return action.dest;
  }
  return null;
}

/**
 * SystemExit raised by ArgumentParser.exit()/error(). The caller is expected to
 * translate `status` into the process exit code, exactly like CPython does when
 * SystemExit escapes main().
 */
export class ArgumentParserExit extends PyException {
  /**
   * @param {number} status process exit status
   * @param {string|null} message already-formatted text (already written out)
   */
  constructor(status = 0, message = null) {
    super(message === null ? String(status) : message, 'SystemExit');
    this.status = status;
    this.exitMessage = message;
  }
}

/** construct.ConstructError */
export class ConstructError extends PyException {
  constructor(message, pyName = 'ConstructError') {
    super(message, pyName);
  }
}

/** construct.StreamError - not enough bytes, bad offsets, etc. */
export class StreamError extends ConstructError {
  constructor(message) {
    super(message, 'StreamError');
  }
}

/**
 * Emulates CPython's repr() for str objects (unicode_repr in
 * Objects/unicodeobject.c). Used for argparse's
 * "invalid int value: <repr>" message.
 *
 * Rules reproduced here:
 *   - Quote choice: single quotes by default; if the string contains a single
 *     quote and no double quote, wrap in double quotes instead (and leave the
 *     single quote unescaped).
 *   - Escapes: backslash, the delimiter quote, \n, \r, \t. There are no
 *     \a \b \v \f shortcuts - those become \x07 \x08 \x0b \x0c.
 *   - Any non-printable code point (Unicode categories Cc, Cf, Cs, Co, Cn, Zl,
 *     Zp, Zs, with U+0020 exempted) is escaped as \xXX (< 0x100),
 *     \uXXXX (< 0x10000) or \UXXXXXXXX, using lowercase hex digits.
 *   - Printable non-ASCII code points are emitted literally.
 */

// str.isprintable(): "Other" and "Separator" categories are not printable.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/**
 * Mirrors Python's str.isprintable() for a single code point.
 * @param {number} cp
 * @returns {boolean}
 */
export function isPrintableCodePoint(cp) {
  if (cp === 0x20) return true; // ASCII space is explicitly printable
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

/**
 * Escape a non-printable code point the way CPython does.
 * @param {number} cp
 * @returns {string}
 */
function escapeCodePoint(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * Python repr() of a string.
 * @param {string} value
 * @returns {string}
 */
export function pythonRepr(value) {
  const text = String(value);
  const hasSingle = text.includes("'");
  const hasDouble = text.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let body = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      body += '\\\\';
    } else if (ch === quote) {
      body += '\\' + ch;
    } else if (cp === 0x0a) {
      body += '\\n';
    } else if (cp === 0x0d) {
      body += '\\r';
    } else if (cp === 0x09) {
      body += '\\t';
    } else if (!isPrintableCodePoint(cp)) {
      body += escapeCodePoint(cp);
    } else {
      body += ch;
    }
  }
  return quote + body + quote;
}

export default pythonRepr;

/**
 * Faithful port of CPython's int(str) (PyNumber_Long / PyLong_FromUnicodeObject
 * with base 10). Returns a BigInt so arbitrarily large literals survive.
 *
 * Reproduced behaviour:
 *   - Leading and trailing Unicode whitespace (the exact set CPython treats as
 *     whitespace) is stripped; whitespace anywhere else is rejected.
 *   - An optional single '+'/'-' sign must sit immediately before the digits.
 *   - Underscores are allowed only as single separators between two digits.
 *   - Any Unicode decimal digit (general category Nd) is accepted, from any
 *     script, freely mixed, including astral-plane digits.
 *   - CPython's sys.int_max_str_digits limit (4300 by default) applies to the
 *     number of digit characters; exceeding it raises ValueError.
 *   - Everything else ('', ' ', '0x10', '1e2', '91.0', '1_', '++5', ...) raises
 *     ValueError, which argparse turns into "invalid int value: <repr>".
 */

import { PyValueError } from '../errors.mjs';
import { pythonRepr } from './repr.mjs';

/**
 * Code points for which CPython's Py_UNICODE_ISSPACE() is true and which
 * str.strip() therefore removes. Note that U+0085 is included (JS trim() does
 * not strip it) while U+FEFF is not (JS trim() does strip it), so a plain
 * String.prototype.trim() would be wrong on exactly those two code points.
 */
export const PY_WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
  0x85, 0xa0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

/**
 * The whitespace set actually accepted around an integer literal. CPython's
 * int() skips characters for which Py_UNICODE_ISSPACE() is true, but the
 * reference program rejects U+001C..U+001F, so those file separators are not
 * part of the accepted set here.
 */
const INT_WHITESPACE = new Set(
  [...PY_WHITESPACE].filter((cp) => cp < 0x1c || cp > 0x1f),
);

/** Default value of sys.int_max_str_digits in CPython 3.11+. */
export const INT_MAX_STR_DIGITS = 4300;

const ND = /\p{Nd}/u;
const digitValueCache = new Map();

/**
 * Numeric value 0-9 of a Unicode decimal digit, or -1 when the code point is
 * not in general category Nd.
 *
 * Unicode encodes every decimal digit set as an ascending contiguous run that
 * starts at that script's zero, so the value is the offset from the start of
 * the run. A few runs are several sets long (the mathematical alphanumerics
 * block holds five back-to-back sets), hence the modulo.
 *
 * @param {number} cp
 * @returns {number}
 */
export function decimalDigitValue(cp) {
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30; // ASCII fast path
  const cached = digitValueCache.get(cp);
  if (cached !== undefined) return cached;

  let value = -1;
  if (ND.test(String.fromCodePoint(cp))) {
    let start = cp;
    while (start > 0 && ND.test(String.fromCodePoint(start - 1))) start -= 1;
    value = (cp - start) % 10;
  }
  digitValueCache.set(cp, value);
  return value;
}

/**
 * True when the code point is a Unicode decimal digit.
 * @param {number} cp
 * @returns {boolean}
 */
export function isDecimalDigit(cp) {
  return decimalDigitValue(cp) >= 0;
}

/**
 * Python's str.strip() restricted to the whitespace set int() honours.
 * @param {string} text
 * @returns {string}
 */
export function stripPythonWhitespace(text) {
  const points = Array.from(text);
  let first = 0;
  let last = points.length;
  while (first < last && INT_WHITESPACE.has(points[first].codePointAt(0))) first += 1;
  while (last > first && INT_WHITESPACE.has(points[last - 1].codePointAt(0))) last -= 1;
  return points.slice(first, last).join('');
}

/**
 * int(text) with base 10.
 * @param {string} text
 * @returns {bigint}
 * @throws {PyValueError}
 */
export function pythonInt(text) {
  const raw = String(text);
  const invalid = () => new PyValueError(
    `invalid literal for int() with base 10: ${pythonRepr(raw)}`,
  );

  const body = stripPythonWhitespace(raw);
  const points = Array.from(body);
  let index = 0;

  let negative = false;
  if (points.length > 0 && (points[0] === '+' || points[0] === '-')) {
    negative = points[0] === '-';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  let pendingUnderscore = false;
  for (; index < points.length; index += 1) {
    const ch = points[index];
    if (ch === '_') {
      // Only a single underscore, and only strictly between two digits.
      if (!previousWasDigit || pendingUnderscore) throw invalid();
      pendingUnderscore = true;
      previousWasDigit = false;
      continue;
    }
    const value = decimalDigitValue(ch.codePointAt(0));
    if (value < 0) throw invalid();
    digits += String(value);
    previousWasDigit = true;
    pendingUnderscore = false;
  }

  // Empty digit string, or a trailing underscore, is a syntax error.
  if (digits.length === 0 || pendingUnderscore) throw invalid();

  // CPython refuses to convert absurdly long literals; the limit counts digit
  // characters only, so sign, underscores and whitespace do not contribute.
  if (digits.length > INT_MAX_STR_DIGITS) {
    throw new PyValueError(
      `Exceeds the limit (${INT_MAX_STR_DIGITS} digits) for integer string ` +
      `conversion: value has ${digits.length} digits; use ` +
      'sys.set_int_max_str_digits() to increase the limit',
    );
  }

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

// argparse reports the failing converter by its __name__, which for the
// original program is the builtin "int".
pythonInt.typeName = 'int';

export default pythonInt;

/**
 * Emulates the builtin bytes(iterable_of_ints) constructor on top of
 * node:buffer. Every element must be an integer in range(0, 256); otherwise
 * CPython raises ValueError("bytes must be in range(0, 256)"), which is exactly
 * the failure the original program hits for out-of-range --a/--b values.
 */

import { Buffer } from 'node:buffer';
import { PyTypeError, PyValueError } from '../errors.mjs';

/**
 * Coerce one element to an integer the way bytes() does.
 * @param {number|bigint} item
 * @returns {bigint}
 */
function asInteger(item) {
  if (typeof item === 'bigint') return item;
  if (typeof item === 'number') {
    if (!Number.isInteger(item)) {
      throw new PyTypeError("'float' object cannot be interpreted as an integer");
    }
    return BigInt(item);
  }
  throw new PyTypeError(
    `cannot convert '${typeof item}' object to bytes`,
  );
}

/**
 * bytes(iterable) -> Buffer.
 * @param {Iterable<number|bigint>} values
 * @returns {Buffer}
 * @throws {PyValueError} when any value falls outside 0..255
 */
export function pythonBytes(values) {
  const octets = [];
  for (const item of values) {
    const value = asInteger(item);
    if (value < 0n || value > 255n) {
      throw new PyValueError('bytes must be in range(0, 256)');
    }
    octets.push(Number(value));
  }
  return Buffer.from(octets);
}

/**
 * bytes(n) -> Buffer of n zero bytes (the integer form of the constructor).
 * @param {number|bigint} size
 * @returns {Buffer}
 */
export function pythonZeroBytes(size) {
  const count = Number(asInteger(size));
  if (count < 0) throw new PyValueError('negative count');
  return Buffer.alloc(count);
}

export default pythonBytes;

/**
 * Renders the stderr reports that the PyInstaller-frozen test4 program emits.
 *
 * Two shapes are reproduced:
 *   1. An unhandled exception escaping main(): CPython's traceback followed by
 *      PyInstaller's "[PYI-<pid>:ERROR] Failed to execute script ..." line.
 *      Because the frozen build ships no .py source, linecache finds nothing,
 *      so the frames carry NO source line and NO caret line.
 *   2. The interpreter-shutdown reports produced when writing/flushing stdout
 *      fails (broken pipe, no space left on device).
 */

import process from 'node:process';

/** Script name PyInstaller reports; it is the module name, not the exe name. */
export const SCRIPT_NAME = 'test4';

/** Source file recorded in the frozen code objects. */
export const SOURCE_FILE = 'test4.py';

/**
 * Call stack of the original program at the point bytes() fails:
 * module level called main(), main() called bytes().
 * @type {ReadonlyArray<{file: string, line: number, name: string}>}
 */
export const MAIN_TRACEBACK_FRAMES = Object.freeze([
  Object.freeze({ file: SOURCE_FILE, line: 20, name: '<module>' }),
  Object.freeze({ file: SOURCE_FILE, line: 15, name: 'main' }),
]);

/**
 * Format a CPython traceback body (header plus frames, no exception line).
 * @param {ReadonlyArray<{file: string, line: number, name: string}>} frames
 * @returns {string}
 */
export function formatTracebackFrames(frames) {
  let text = 'Traceback (most recent call last):\n';
  for (const frame of frames) {
    text += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
  }
  return text;
}

/**
 * Full traceback text for an exception escaping the frozen script.
 * @param {{pyName?: string, name?: string, message: string}} error
 * @param {{frames?: ReadonlyArray<{file: string, line: number, name: string}>, pid?: number}} [options]
 * @returns {string}
 */
export function formatUnhandledException(error, options = {}) {
  const frames = options.frames ?? MAIN_TRACEBACK_FRAMES;
  const pid = options.pid ?? process.pid;
  const className = error.pyName ?? error.name ?? 'Exception';
  return (
    formatTracebackFrames(frames) +
    `${className}: ${error.message}\n` +
    `[PYI-${pid}:ERROR] Failed to execute script '${SCRIPT_NAME}' due to ` +
    'unhandled exception!\n'
  );
}

/**
 * Write the unhandled-exception report to stderr.
 * @param {{pyName?: string, name?: string, message: string}} error
 * @param {{frames?: ReadonlyArray<{file: string, line: number, name: string}>, pid?: number, stream?: NodeJS.WritableStream}} [options]
 */
export function reportUnhandledException(error, options = {}) {
  const stream = options.stream ?? process.stderr;
  stream.write(formatUnhandledException(error, options));
}

/**
 * Report emitted when stdout cannot be written or flushed during interpreter
 * shutdown. The frozen bootloader's frame is `File "<string>", line 1`, and no
 * "[PYI-...]" line is printed because the failure happens after the script has
 * already returned.
 *
 * @param {string} className Python exception class, e.g. "BrokenPipeError"
 * @param {string} message text after "ClassName: "
 * @returns {string}
 */
export function formatShutdownIOError(className, message) {
  const frames = [{ file: '<string>', line: 1, name: '<module>' }];
  return (
    formatTracebackFrames(frames) +
    `${className}: ${message}\n` +
    "Exception ignored in: <_io.TextIOWrapper name='<stdout>' mode='w' " +
    "encoding='utf-8'>\n" +
    `${className}: ${message}\n`
  );
}

/** Exact report seen when stdout's reader goes away (EPIPE). */
export const BROKEN_PIPE_REPORT = formatShutdownIOError(
  'BrokenPipeError',
  '[Errno 32] Broken pipe',
);

/** Exact report seen when stdout's target is full (ENOSPC). */
export const NO_SPACE_REPORT = formatShutdownIOError(
  'OSError',
  '[Errno 28] No space left on device',
);

/**
 * Map a Node stream error to the matching Python shutdown report.
 * @param {{code?: string}} error
 * @returns {string|null} report text, or null when the failure has no analogue
 */
export function shutdownReportForStreamError(error) {
  switch (error && error.code) {
    case 'EPIPE':
      return BROKEN_PIPE_REPORT;
    case 'ENOSPC':
      return NO_SPACE_REPORT;
    default:
      return null;
  }
}

/**
 * Emulates argparse.HelpFormatter: the usage line, the "options:" section and
 * all of the terminal-width dependent wrapping.
 *
 * Layout constants mirror CPython:
 *   indent_increment   = 2
 *   max_help_position  = min(24, max(width - 20, 4))
 *   help_position      = min(action_max_length + 2, max_help_position)
 *   help_width         = max(width - help_position, 11)
 *   width              = terminal columns - 2
 * where the terminal columns come from $COLUMNS when it parses as a positive
 * integer, else the real terminal size of stdout, else 80.
 */

import process from 'node:process';
import { pythonInt } from '../python/int.mjs';

const USAGE_PREFIX = 'usage: ';

/** Fallback terminal size used by shutil.get_terminal_size(). */
export const FALLBACK_COLUMNS = 80;

/**
 * shutil.get_terminal_size().columns
 * @returns {number}
 */
export function terminalColumns() {
  const raw = process.env.COLUMNS;
  if (raw !== undefined) {
    try {
      // Python parses $COLUMNS with int(), so the full int() syntax applies.
      const parsed = pythonInt(raw);
      if (parsed > 0n) return Number(parsed);
    } catch {
      // Not an integer: fall through to the terminal query.
    }
  }
  if (process.stdout && process.stdout.isTTY && process.stdout.columns > 0) {
    return process.stdout.columns;
  }
  return FALLBACK_COLUMNS;
}

/**
 * textwrap.wrap() with argparse's defaults (greedy fill, long words broken).
 * @param {string} text
 * @param {number} width
 * @returns {string[]}
 */
export function wrapText(text, width) {
  const limit = Math.max(1, width);
  const words = text.replace(/\s+/gu, ' ').trim().split(' ').filter(Boolean);
  const lines = [];
  let current = '';
  for (let word of words) {
    while (word.length > limit) {
      if (current) {
        lines.push(current);
        current = '';
      }
      lines.push(word.slice(0, limit));
      word = word.slice(limit);
    }
    if (!current) current = word;
    else if (current.length + 1 + word.length <= limit) current += ' ' + word;
    else {
      lines.push(current);
      current = word;
    }
  }
  if (current) lines.push(current);
  return lines;
}

/** Repeat a space `count` times (never negative). */
function spaces(count) {
  return count > 0 ? ' '.repeat(count) : '';
}

export class HelpFormatter {
  /**
   * @param {string} prog program name shown in usage
   * @param {{indentIncrement?: number, maxHelpPosition?: number, width?: number}} [options]
   */
  constructor(prog, options = {}) {
    this.prog = prog;
    this.indentIncrement = options.indentIncrement ?? 2;
    this.width = options.width ?? terminalColumns() - 2;
    this.maxHelpPosition = Math.min(
      options.maxHelpPosition ?? 24,
      Math.max(this.width - 20, this.indentIncrement * 2),
    );
  }

  /** argparse._get_default_metavar_for_optional: the upper-cased dest. */
  metavarFor(action) {
    if (action.metavar !== undefined && action.metavar !== null) return action.metavar;
    return String(action.dest).toUpperCase();
  }

  /** argparse.HelpFormatter._format_args for the nargs values we support. */
  formatArgs(action) {
    const metavar = this.metavarFor(action);
    if (action.nargs === 0) return '';
    if (action.nargs === null || action.nargs === undefined) return metavar;
    if (typeof action.nargs === 'number') {
      return Array.from({ length: action.nargs }, () => metavar).join(' ');
    }
    if (action.nargs === '?') return `[${metavar}]`;
    if (action.nargs === '*') return `[${metavar} ...]`;
    if (action.nargs === '+') return `${metavar} [${metavar} ...]`;
    return metavar;
  }

  /** e.g. "-h, --help" or "--a A" */
  formatActionInvocation(action) {
    if (!action.optionStrings || action.optionStrings.length === 0) {
      return this.metavarFor(action);
    }
    const argsString = this.formatArgs(action);
    const joined = action.optionStrings.join(', ');
    return argsString ? `${joined} ${argsString}` : joined;
  }

  /** The bracketed form used inside the usage line. */
  formatActionUsage(action) {
    const optionString = action.optionStrings[0];
    const argsString = this.formatArgs(action);
    const part = argsString ? `${optionString} ${argsString}` : optionString;
    return action.required ? part : `[${part}]`;
  }

  /**
   * argparse.HelpFormatter._format_usage.
   * @param {Array<object>} actions
   * @returns {string} "usage: ...\n" (single trailing newline)
   */
  formatUsage(actions) {
    const prog = this.prog;
    const optionals = actions.filter((a) => a.optionStrings.length > 0);
    const positionals = actions.filter((a) => a.optionStrings.length === 0);
    const optUsage = optionals.map((a) => this.formatActionUsage(a)).join(' ');
    const posUsage = positionals.map((a) => this.formatActionUsage(a)).join(' ');
    let usage = [prog, optUsage, posUsage].filter((s) => s).join(' ');

    const textWidth = this.width;
    if (USAGE_PREFIX.length + usage.length > textWidth) {
      // Split the usage into wrappable parts, keeping bracketed groups intact.
      const partRegexp = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;
      const optParts = optUsage.match(partRegexp) ?? [];
      const posParts = posUsage.match(partRegexp) ?? [];

      const getLines = (parts, indent, prefix) => {
        const lines = [];
        let line = [];
        let lineLen = (prefix !== undefined ? prefix.length : indent.length) - 1;
        for (const part of parts) {
          if (lineLen + 1 + part.length > textWidth && line.length > 0) {
            lines.push(indent + line.join(' '));
            line = [];
            lineLen = indent.length - 1;
          }
          line.push(part);
          lineLen += 1 + part.length;
        }
        if (line.length > 0) lines.push(indent + line.join(' '));
        if (prefix !== undefined && lines.length > 0) {
          lines[0] = lines[0].slice(indent.length);
        }
        return lines;
      };

      let lines;
      if (USAGE_PREFIX.length + prog.length <= 0.75 * textWidth) {
        // Short prog: the first line carries the prog plus as much as fits.
        const indent = spaces(USAGE_PREFIX.length + prog.length + 1);
        if (optParts.length > 0) {
          lines = getLines([prog, ...optParts], indent, USAGE_PREFIX);
          lines.push(...getLines(posParts, indent));
        } else if (posParts.length > 0) {
          lines = getLines([prog, ...posParts], indent, USAGE_PREFIX);
        } else {
          lines = [prog];
        }
      } else {
        // Long prog: it gets a line of its own.
        const indent = spaces(USAGE_PREFIX.length);
        let body = getLines([...optParts, ...posParts], indent);
        if (body.length > 1) {
          body = [...getLines(optParts, indent), ...getLines(posParts, indent)];
        }
        lines = [prog, ...body];
      }
      usage = lines.join('\n');
    }
    return `${USAGE_PREFIX}${usage}\n`;
  }

  /** Longest invocation plus the section indent (argparse._action_max_length). */
  actionMaxLength(actions) {
    let max = 0;
    for (const action of actions) {
      const length = this.formatActionInvocation(action).length + this.indentIncrement;
      if (length > max) max = length;
    }
    return max;
  }

  /**
   * argparse.HelpFormatter._format_action for one option.
   * @param {object} action
   * @param {number} helpPosition
   * @returns {string}
   */
  formatAction(action, helpPosition) {
    const currentIndent = this.indentIncrement;
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - currentIndent - 2;
    const invocation = this.formatActionInvocation(action);

    let header;
    let indentFirst = 0;
    if (!action.help) {
      // No help text: the invocation is the whole line.
      header = spaces(currentIndent) + invocation + '\n';
    } else if (invocation.length <= actionWidth) {
      header = spaces(currentIndent) + invocation.padEnd(actionWidth) + '  ';
      indentFirst = 0;
    } else {
      header = spaces(currentIndent) + invocation + '\n';
      indentFirst = helpPosition;
    }

    let text = header;
    if (action.help && action.help.trim()) {
      const helpLines = wrapText(action.help, helpWidth);
      text += spaces(indentFirst) + helpLines[0] + '\n';
      for (const line of helpLines.slice(1)) {
        text += spaces(helpPosition) + line + '\n';
      }
    } else if (!header.endsWith('\n')) {
      text += '\n';
    }
    return text;
  }

  /**
   * Full help text: usage, then one section per group of actions.
   * @param {Array<object>} actions
   * @param {Array<{title: string, actions: Array<object>}>} sections
   * @returns {string}
   */
  formatHelp(actions, sections) {
    const helpPosition = Math.min(
      this.actionMaxLength(actions) + 2,
      this.maxHelpPosition,
    );

    let text = this.formatUsage(actions) + '\n';
    for (const section of sections) {
      if (section.actions.length === 0) continue;
      text += `${section.title}:\n`;
      for (const action of section.actions) {
        text += this.formatAction(action, helpPosition);
      }
      text += '\n';
    }
    // argparse collapses long runs of blank lines and normalises the ending.
    text = text.replace(/\n\n\n+/g, '\n\n');
    return text.replace(/^\n+/, '').replace(/\n+$/, '') + '\n';
  }
}

export default HelpFormatter;

/**
 * Emulates the parts of argparse.ArgumentParser that the original program
 * exercises: add_argument for long options with a `type` converter,
 * prefix-abbreviation matching, the "--opt=value" form, grouped single-dash
 * options, the "--" separator, required-option checks, leftover collection and
 * error()/exit() with argparse's exit codes.
 *
 * The parse order is CPython's, which is what makes the observable precedence
 * work out: option strings are classified in one left-to-right pre-pass (where
 * an ambiguous abbreviation errors immediately), then consumed left-to-right
 * (where "ignored explicit argument", "expected one argument" and type
 * conversion errors fire, and where -h prints help and exits), then the
 * required-argument check runs, and only then are leftovers reported.
 */

import process from 'node:process';
import path from 'node:path';

import {
  ArgumentError,
  ArgumentParserExit,
  ArgumentTypeError,
  PyTypeError,
  PyValueError,
} from '../errors.mjs';
import { pythonRepr } from '../python/repr.mjs';
import { HelpFormatter } from './formatter.mjs';

/** argparse.SUPPRESS */
export const SUPPRESS = '==SUPPRESS==';

/**
 * Python's argparse._negative_number_matcher, made Unicode-aware like Python's
 * `\d`. Python's `$` also matches just before a single trailing newline, so the
 * optional `\n?` reproduces that quirk.
 */
const NEGATIVE_NUMBER_MATCHER = /^(?:-\p{Nd}+|-\p{Nd}*\.\p{Nd}+)\n?$/u;

/** One parsed argument definition (argparse.Action). */
export class Action {
  /**
   * @param {{
   *   optionStrings: string[], dest: string, nargs?: number|string|null,
   *   type?: ((value: string) => unknown)|null, required?: boolean,
   *   help?: string|null, metavar?: string|null, kind?: 'store'|'help',
   *   defaultValue?: unknown,
   * }} spec
   */
  constructor(spec) {
    this.optionStrings = spec.optionStrings ?? [];
    this.dest = spec.dest;
    this.nargs = spec.nargs === undefined ? null : spec.nargs;
    this.type = spec.type ?? null;
    this.required = spec.required ?? false;
    this.help = spec.help ?? null;
    this.metavar = spec.metavar ?? null;
    this.kind = spec.kind ?? 'store';
    this.defaultValue = spec.defaultValue === undefined ? null : spec.defaultValue;
  }

  /**
   * argparse.Action.__call__
   * @param {ArgumentParser} parser
   * @param {Record<string, unknown>} namespace
   * @param {unknown} values
   * @param {string|null} optionString
   */
  invoke(parser, namespace, values, optionString) {
    if (this.kind === 'help') {
      parser.printHelp();
      parser.exit(0);
      return;
    }
    namespace[this.dest] = values;
  }
}

/**
 * argparse.ArgumentParser.
 */
export class ArgumentParser {
  /**
   * @param {{
   *   prog?: string, addHelp?: boolean, allowAbbrev?: boolean,
   *   prefixChars?: string, formatterClass?: typeof HelpFormatter,
   *   stdout?: NodeJS.WritableStream, stderr?: NodeJS.WritableStream,
   * }} [options]
   */
  constructor(options = {}) {
    // Python defaults prog to os.path.basename(sys.argv[0]).
    this.prog = options.prog ?? defaultProgName();
    this.prefixChars = options.prefixChars ?? '-';
    this.allowAbbrev = options.allowAbbrev ?? true;
    this.formatterClass = options.formatterClass ?? HelpFormatter;
    this._stdout = options.stdout ?? process.stdout;
    this._stderr = options.stderr ?? process.stderr;

    this._actions = [];
    /** @type {Map<string, Action>} insertion order drives abbreviation search */
    this._optionStringActions = new Map();
    // Non-empty only when an option string itself looks like a negative number.
    this._hasNegativeNumberOptionals = false;
    this._groups = [
      { title: 'positional arguments', actions: [] },
      { title: 'options', actions: [] },
    ];

    if (options.addHelp ?? true) {
      this.addArgument(['-h', '--help'], {
        nargs: 0,
        kind: 'help',
        help: 'show this help message and exit',
        defaultValue: SUPPRESS,
        dest: 'help',
      });
    }
  }

  /**
   * add_argument for options and positionals.
   * @param {string|string[]} names
   * @param {object} [options]
   * @returns {Action}
   */
  addArgument(names, options = {}) {
    const optionStrings = (Array.isArray(names) ? names : [names]).filter(Boolean);
    const isOption = optionStrings.length > 0 &&
      this.prefixChars.includes(optionStrings[0][0]);

    let dest = options.dest;
    if (dest === undefined) {
      if (isOption) {
        const longOptions = optionStrings.filter(
          (s) => s.length > 1 && this.prefixChars.includes(s[1]),
        );
        const source = longOptions.length > 0 ? longOptions[0] : optionStrings[0];
        dest = stripPrefixChars(source, this.prefixChars).replace(/-/g, '_');
      } else {
        dest = optionStrings[0];
      }
    }

    const action = new Action({
      optionStrings: isOption ? optionStrings : [],
      dest,
      nargs: options.nargs,
      type: options.type,
      required: options.required ?? isOption === false,
      help: options.help,
      metavar: options.metavar,
      kind: options.kind,
      defaultValue: options.defaultValue,
    });

    this._actions.push(action);
    this._groups[isOption ? 1 : 0].actions.push(action);
    for (const optionString of action.optionStrings) {
      this._optionStringActions.set(optionString, action);
      if (NEGATIVE_NUMBER_MATCHER.test(optionString)) {
        this._hasNegativeNumberOptionals = true;
      }
    }
    return action;
  }

  /** @returns {HelpFormatter} */
  _getFormatter() {
    return new this.formatterClass(this.prog);
  }

  /** "usage: prog [-h] --a A --b B\n" */
  formatUsage() {
    return this._getFormatter().formatUsage(this._actions);
  }

  /** Full help text. */
  formatHelp() {
    return this._getFormatter().formatHelp(this._actions, this._groups);
  }

  /** @param {NodeJS.WritableStream} [stream] */
  printUsage(stream) {
    (stream ?? this._stdout).write(this.formatUsage());
  }

  /** @param {NodeJS.WritableStream} [stream] */
  printHelp(stream) {
    (stream ?? this._stdout).write(this.formatHelp());
  }

  /**
   * argparse.ArgumentParser.exit - writes `message` to stderr, then raises
   * SystemExit (here: ArgumentParserExit) so the caller can exit.
   * @param {number} [status]
   * @param {string|null} [message]
   */
  exit(status = 0, message = null) {
    if (message) this._stderr.write(message);
    throw new ArgumentParserExit(status, message);
  }

  /**
   * argparse.ArgumentParser.error - usage plus "<prog>: error: <message>" on
   * stderr, exit status 2.
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    this.printUsage(this._stderr);
    this.exit(2, `${this.prog}: error: ${message}\n`);
    throw new Error('unreachable');
  }

  /**
   * parse_args: like parse_known_args, but leftovers are a hard error.
   * @param {string[]} [args] defaults to process.argv.slice(2)
   * @returns {Record<string, unknown>}
   */
  parseArgs(args) {
    const [namespace, extras] = this.parseKnownArgs(args);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /**
   * parse_known_args
   * @param {string[]} [args]
   * @param {Record<string, unknown>} [namespace]
   * @returns {[Record<string, unknown>, string[]]}
   */
  parseKnownArgs(args, namespace) {
    const argStrings = args ?? process.argv.slice(2);
    const ns = namespace ?? Object.create(null);

    // Seed defaults, exactly as argparse does before parsing.
    for (const action of this._actions) {
      if (!(action.dest in ns) && action.defaultValue !== SUPPRESS) {
        ns[action.dest] = action.defaultValue;
      }
    }

    try {
      return this._parseKnownArgs(argStrings, ns);
    } catch (err) {
      if (err instanceof ArgumentError) {
        this.error(String(err));
      }
      throw err;
    }
  }

  /**
   * The core of argparse._parse_known_args.
   * @param {string[]} argStrings
   * @param {Record<string, unknown>} namespace
   * @returns {[Record<string, unknown>, string[]]}
   */
  _parseKnownArgs(argStrings, namespace) {
    /** @type {Map<number, [Action|null, string, string|null, string|null]>} */
    const optionStringIndices = new Map();
    let patternParts = [];

    // Pass 1: classify every token as an option ('O'), a plain argument ('A')
    // or the "--" separator ('-'). Everything after "--" is a plain argument.
    for (let i = 0; i < argStrings.length; i += 1) {
      const argString = argStrings[i];
      if (argString === '--') {
        patternParts.push('-');
        for (let j = i + 1; j < argStrings.length; j += 1) patternParts.push('A');
        break;
      }
      const optionTuple = this._parseOptional(argString);
      if (optionTuple === null) {
        patternParts.push('A');
      } else {
        optionStringIndices.set(i, optionTuple);
        patternParts.push('O');
      }
    }
    const argStringsPattern = patternParts.join('');

    const seenActions = new Set();
    const extras = [];
    const positionals = this._actions.filter((a) => a.optionStrings.length === 0);

    const takeAction = (action, argumentStrings, optionString = null) => {
      seenActions.add(action);
      const argumentValues = this._getValues(action, argumentStrings);
      action.invoke(this, namespace, argumentValues, optionString);
    };

    const consumePositionals = (startIndex) => {
      const selectedPattern = argStringsPattern.slice(startIndex);
      const argCounts = this._matchArgumentsPartial(positionals, selectedPattern);
      let index = startIndex;
      for (let i = 0; i < argCounts.length; i += 1) {
        const action = positionals[i];
        const args = argStrings.slice(index, index + argCounts[i]);
        index += argCounts[i];
        takeAction(action, args);
      }
      positionals.splice(0, argCounts.length);
      return index;
    };

    const consumeOptional = (startIndex) => {
      let [action, optionString, sep, explicitArg] = optionStringIndices.get(startIndex);
      const argString = argStrings[startIndex];
      const actionTuples = [];
      let stop = startIndex + 1;

      for (;;) {
        if (action === null) {
          // Unknown option string: keep the original token as a leftover.
          extras.push(argString);
          return startIndex + 1;
        }

        if (explicitArg !== null) {
          const argCount = this._matchArgument(action, 'A');
          const takesNoArgs = argCount === 0;
          const isShortOption = !this.prefixChars.includes(optionString[1]);
          if (takesNoArgs && isShortOption && explicitArg !== '') {
            if (sep || this.prefixChars.includes(explicitArg[0])) {
              throw new ArgumentError(
                action,
                `ignored explicit argument ${pythonRepr(explicitArg)}`,
              );
            }
            // "-hx" is "-h" followed by more single-dash options.
            actionTuples.push([action, [], optionString]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            if (this._optionStringActions.has(optionString)) {
              action = this._optionStringActions.get(optionString);
              explicitArg = explicitArg.slice(1);
              if (explicitArg === '') {
                sep = null;
                explicitArg = null;
              } else if (explicitArg[0] === '=') {
                sep = '=';
                explicitArg = explicitArg.slice(1);
              } else {
                sep = '';
              }
            } else {
              extras.push(char + explicitArg);
              stop = startIndex + 1;
              break;
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          } else {
            throw new ArgumentError(
              action,
              `ignored explicit argument ${pythonRepr(explicitArg)}`,
            );
          }
        } else {
          // Values come from the following tokens.
          const start = startIndex + 1;
          const argCount = this._matchArgument(action, argStringsPattern.slice(start));
          stop = start + argCount;
          actionTuples.push([action, argStrings.slice(start, stop), optionString]);
          break;
        }
      }

      for (const [act, args, optStr] of actionTuples) takeAction(act, args, optStr);
      return stop;
    };

    let startIndex = 0;
    const optionIndices = [...optionStringIndices.keys()];
    const maxOptionStringIndex = optionIndices.length > 0
      ? Math.max(...optionIndices)
      : -1;

    while (startIndex <= maxOptionStringIndex) {
      const nextOptionStringIndex = Math.min(
        ...optionIndices.filter((index) => index >= startIndex),
      );
      if (startIndex !== nextOptionStringIndex) {
        const positionalsEndIndex = consumePositionals(startIndex);
        if (positionalsEndIndex > startIndex) {
          startIndex = positionalsEndIndex;
          continue;
        }
        startIndex = positionalsEndIndex;
        if (startIndex !== nextOptionStringIndex) {
          extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
          startIndex = nextOptionStringIndex;
        }
      }
      startIndex = consumeOptional(startIndex);
    }

    const stopIndex = consumePositionals(startIndex);
    extras.push(...argStrings.slice(stopIndex));

    // Required options are only checked once every token has been consumed,
    // which is why help and consumption-time errors both beat this message.
    const requiredActions = [];
    for (const action of this._actions) {
      if (!seenActions.has(action) && action.required) {
        requiredActions.push(actionName(action));
      }
    }
    if (requiredActions.length > 0) {
      this.error(
        `the following arguments are required: ${requiredActions.join(', ')}`,
      );
    }

    return [namespace, extras];
  }

  /**
   * argparse._parse_optional: decide whether a token is an option, and which.
   * @param {string} argString
   * @returns {[Action|null, string, string|null, string|null]|null}
   */
  _parseOptional(argString) {
    if (!argString) return null;
    if (!this.prefixChars.includes(argString[0])) return null;

    if (this._optionStringActions.has(argString)) {
      return [this._optionStringActions.get(argString), argString, null, null];
    }
    if (argString.length === 1) return null;

    const equalsIndex = argString.indexOf('=');
    if (equalsIndex !== -1) {
      const optionString = argString.slice(0, equalsIndex);
      const explicitArg = argString.slice(equalsIndex + 1);
      if (this._optionStringActions.has(optionString)) {
        return [this._optionStringActions.get(optionString), optionString, '=', explicitArg];
      }
    }

    const optionTuples = this._getOptionTuples(argString);
    if (optionTuples.length > 1) {
      const matches = optionTuples.map((tuple) => tuple[1]).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (optionTuples.length === 1) {
      return optionTuples[0];
    }

    // Negative numbers are positionals as long as no option looks like one.
    if (NEGATIVE_NUMBER_MATCHER.test(argString) && !this._hasNegativeNumberOptionals) {
      return null;
    }
    // A token containing a space was meant to be a value.
    if (argString.includes(' ')) return null;

    return [null, argString, null, null];
  }

  /**
   * argparse._get_option_tuples: prefix matches for abbreviations and grouped
   * single-dash options.
   * @param {string} optionString
   * @returns {Array<[Action, string, string|null, string|null]>}
   */
  _getOptionTuples(optionString) {
    const result = [];
    const chars = this.prefixChars;
    const startsLong = chars.includes(optionString[0]) && chars.includes(optionString[1]);
    const startsShort = chars.includes(optionString[0]) && !chars.includes(optionString[1]);

    if (startsLong) {
      if (this.allowAbbrev) {
        const equalsIndex = optionString.indexOf('=');
        const optionPrefix = equalsIndex === -1
          ? optionString
          : optionString.slice(0, equalsIndex);
        const sep = equalsIndex === -1 ? null : '=';
        const explicitArg = equalsIndex === -1
          ? null
          : optionString.slice(equalsIndex + 1);
        for (const [candidate, action] of this._optionStringActions) {
          if (candidate.startsWith(optionPrefix)) {
            result.push([action, candidate, sep, explicitArg]);
          }
        }
      }
    } else if (startsShort) {
      const optionPrefix = optionString;
      const shortOptionPrefix = optionString.slice(0, 2);
      const shortExplicitArg = optionString.slice(2);
      for (const [candidate, action] of this._optionStringActions) {
        if (candidate === shortOptionPrefix) {
          result.push([action, candidate, '', shortExplicitArg]);
        } else if (candidate.startsWith(optionPrefix)) {
          result.push([action, candidate, null, null]);
        }
      }
    } else {
      this.error(`unexpected option string: ${optionString}`);
    }
    return result;
  }

  /**
   * argparse._get_nargs_pattern. Optionals may not swallow "--", so the dash
   * placeholders are stripped for them.
   * @param {Action} action
   * @returns {string}
   */
  _getNargsPattern(action) {
    const nargs = action.nargs;
    let pattern;
    if (nargs === null || nargs === undefined) pattern = '(-*A-*)';
    else if (nargs === 0) pattern = '(-*-*)';
    else if (nargs === '?') pattern = '(-*A?-*)';
    else if (nargs === '*') pattern = '(-*[A-]*)';
    else if (nargs === '+') pattern = '(-*A[A-]*)';
    else pattern = '(-*A-*)'.repeat(1) && `(${'-*A'.repeat(nargs)}-*)`;

    if (action.optionStrings.length > 0) {
      pattern = pattern.split('-*').join('').split('-').join('');
    }
    return pattern;
  }

  /**
   * argparse._match_argument
   * @param {Action} action
   * @param {string} argStringsPattern
   * @returns {number}
   */
  _matchArgument(action, argStringsPattern) {
    const nargsPattern = this._getNargsPattern(action);
    const match = new RegExp('^' + nargsPattern).exec(argStringsPattern);
    if (match === null) {
      const message = action.nargs === null || action.nargs === undefined
        ? 'expected one argument'
        : `expected ${action.nargs} argument(s)`;
      throw new ArgumentError(action, message);
    }
    return match[1].length;
  }

  /**
   * argparse._match_arguments_partial
   * @param {Action[]} actions
   * @param {string} argStringsPattern
   * @returns {number[]}
   */
  _matchArgumentsPartial(actions, argStringsPattern) {
    const result = [];
    for (let i = actions.length; i > 0; i -= 1) {
      const slice = actions.slice(0, i);
      const pattern = '^' + slice.map((a) => this._getNargsPattern(a)).join('');
      const match = new RegExp(pattern).exec(argStringsPattern);
      if (match !== null) {
        for (let g = 1; g < match.length; g += 1) result.push(match[g].length);
        break;
      }
    }
    return result;
  }

  /**
   * argparse._get_values
   * @param {Action} action
   * @param {string[]} argStrings
   * @returns {unknown}
   */
  _getValues(action, argStrings) {
    let strings = [...argStrings];
    // Only positionals drop the "--" separator from their values.
    if (action.optionStrings.length === 0) {
      const index = strings.indexOf('--');
      if (index !== -1) strings.splice(index, 1);
    }
    if (strings.length === 1 && (action.nargs === null || action.nargs === '?')) {
      return this._getValue(action, strings[0]);
    }
    return strings.map((value) => this._getValue(action, value));
  }

  /**
   * argparse._get_value: run the `type` callable and translate failures into
   * "invalid <type> value: <repr>".
   * @param {Action} action
   * @param {string} argString
   * @returns {unknown}
   */
  _getValue(action, argString) {
    const typeFunc = action.type;
    if (!typeFunc) return argString;
    try {
      return typeFunc(argString);
    } catch (err) {
      if (err instanceof ArgumentTypeError) {
        throw new ArgumentError(action, err.message);
      }
      if (err instanceof PyValueError || err instanceof PyTypeError ||
          err instanceof TypeError || err instanceof RangeError) {
        const name = typeFunc.typeName ?? typeFunc.name ?? String(typeFunc);
        throw new ArgumentError(
          action,
          `invalid ${name} value: ${pythonRepr(argString)}`,
        );
      }
      throw err;
    }
