}

/**
 * argparse._get_action_name, re-exported through the parser for convenience.
 * @param {Action} action
 * @returns {string}
 */
function actionName(action) {
  if (action.optionStrings.length > 0) return action.optionStrings.join('/');
  if (action.metavar) return action.metavar;
  return action.dest;
}

/** str.lstrip(prefix_chars) */
function stripPrefixChars(text, prefixChars) {
  let index = 0;
  while (index < text.length && prefixChars.includes(text[index])) index += 1;
  return text.slice(index);
}

/**
 * os.path.basename(sys.argv[0]) equivalent: in Node the script path is
 * process.argv[1].
 * @returns {string}
 */
export function defaultProgName() {
  const argv0 = process.argv[1];
  if (!argv0) return path.basename(process.argv[0] ?? 'program');
  return path.basename(argv0);
}

export default ArgumentParser;

/**
