/**
 * Emulates construct.Container: an ordered dict whose __str__ produces the
 * multi-line "Container: \n    key = value" rendering that the original program
 * prints. Keys beginning with '_' are metadata (construct stores things like
 * _io there) and are hidden from the rendering, and insertion order is
 * preserved.
 */

import { Buffer } from 'node:buffer';

/** Indent unit construct uses per nesting level. */const INDENT_UNIT = '    ';

export class Container {
  /**
   * @param {Iterable<[string, unknown]>|Record<string, unknown>} [entries]
   */
  constructor(entries) {
    if (entries) {
      const pairs = Symbol.iterator in Object(entries)
        ? entries
        : Object.entries(entries);
      for (const [key, value] of pairs) this.set(key, value);
    }
  }

  /**
   * Insert or replace a field, keeping first-insertion order.
   * @param {string} key
   * @param {unknown} value
   * @returns {this}
   */
  set(key, value) {
    this[key] = value;
    return this;
  }

  /**
   * @param {string} key
   * @returns {unknown}
   */
  get(key) {
    return this[key];
  }

  /**
   * @param {string} key
   * @returns {boolean}
   */
  has(key) {
    return Object.prototype.hasOwnProperty.call(this, key);
  }

  /** Field names in insertion order, including the hidden '_' ones. */
  keys() {
    return Object.keys(this);
  }

  /** [key, value] pairs in insertion order. */
  entries() {
    return this.keys().map((key) => [key, this[key]]);
  }

  /** Field names construct shows when rendering. */
  visibleKeys() {
    return this.keys().filter((key) => !key.startsWith('_'));
  }

  /**
   * construct.Container.__str__
   * @param {number} [nesting] indentation level, 1 for a top-level container
   * @returns {string}
   */
  toString(nesting = 1) {
    const indentation = '\n' + INDENT_UNIT.repeat(nesting);
    const parts = ['Container: '];
    for (const key of this.visibleKeys()) {
      parts.push(indentation, String(key), ' = ', renderValue(this[key], nesting));
    }
    return parts.join('');
  }

  /** construct.Container.__repr__ */
  inspect() {
    const body = this.visibleKeys()
      .map((key) => `${key}=${formatRepr(this[key])}`)
      .join(', ');
    return `Container(${body})`;
  }
}

/**
 * construct.ListContainer: a list whose __str__ indents its items.
 */
export class ListContainer extends Array {
  /**
   * @param {number} [nesting]
   * @returns {string}
   */
  toString(nesting = 1) {
    const indentation = '\n' + INDENT_UNIT.repeat(nesting);
    const parts = ['ListContainer: '];
    for (const item of this) {
      parts.push(indentation, renderValue(item, nesting));
    }
    return parts.join('');
  }
}

/**
 * Render one field value the way construct's Container.__str__ does.
 * @param {unknown} value
 * @param {number} nesting
 * @returns {string}
 */
function renderValue(value, nesting) {
  if (value instanceof Container || value instanceof ListContainer) {
    return value.toString(nesting + 1);
  }
  if (Buffer.isBuffer(value)) {
    return `b'${value.toString('hex')}' (total ${value.length})`;
  }
  if (value === null) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  return String(value);
}

/**
 * Minimal repr() used by Container.inspect().
 * @param {unknown} value
 * @returns {string}
 */
function formatRepr(value) {
  if (typeof value === 'string') return `'${value}'`;
  return renderValue(value, 1);
}

export default Container;

/**
 * Emulates construct's core machinery: the Construct base class, Subconstruct,
 * Renamed, Struct, and the Named() helper that stands in for construct's
 * `"name" / subcon` operator (JavaScript has no operator overloading, so
 * `Named("field1", Int8ul)` is the equivalent spelling).
 *
 * Parsing works on a node:buffer Buffer and an offset; every subconstruct
 * returns the parsed value together with the offset it stopped at.
 */

import { Buffer } from 'node:buffer';
import { StreamError } from '../errors.mjs';
import { Container } from './container.mjs';

/** Base class for every format. */
export class Construct {
  constructor() {
    /** @type {string|null} field name once wrapped in Renamed */
    this.name = null;
  }

  /**
   * Parse a whole byte string, like construct's Construct.parse().
   * @param {Buffer|Uint8Array|number[]} data
   * @param {Record<string, unknown>} [context]
   * @returns {unknown}
   */
  parse(data, context = {}) {
    const buffer = Buffer.isBuffer(data) ? data : Buffer.from(data);
    const [value] = this._parse(buffer, 0, context);
    return value;
  }

  /**
   * Parse starting at `offset`.
   * @param {Buffer} buffer
   * @param {number} offset
   * @param {Record<string, unknown>} context
   * @returns {[unknown, number]} value and the offset after it
   */
  _parse(buffer, offset, context) {
    throw new StreamError(`${this.constructor.name} does not implement parsing`);
  }

  /**
   * Build a byte string, like construct's Construct.build().
   * @param {unknown} value
   * @param {Record<string, unknown>} [context]
   * @returns {Buffer}
   */
  build(value, context = {}) {
    throw new StreamError(`${this.constructor.name} does not implement building`);
  }

  /**
   * Fixed size in bytes.
   * @returns {number}
   */
  sizeof() {
    throw new StreamError(`${this.constructor.name} has no fixed size`);
  }

  /**
   * construct's `"name" / subcon`, expressed as a method for fluent use.
   * @param {string} name
   * @returns {Renamed}
   */
  named(name) {
    return new Renamed(this, name);
  }
}

/** Base class for formats that wrap another format. */
export class Subconstruct extends Construct {
  /**
   * @param {Construct} subcon
   */
  constructor(subcon) {
    super();
    this.subcon = subcon;
    this.name = subcon ? subcon.name : null;
  }

  _parse(buffer, offset, context) {
    return this.subcon._parse(buffer, offset, context);
  }

  build(value, context = {}) {
    return this.subcon.build(value, context);
  }

  sizeof() {
    return this.subcon.sizeof();
  }
}

/** construct.Renamed: attaches a field name to a format. */
export class Renamed extends Subconstruct {
  /**
   * @param {Construct} subcon
   * @param {string} name
   */
  constructor(subcon, name) {
    super(subcon);
    this.name = name;
  }

  toString() {
    return `Renamed(${this.name})`;
  }
}

/**
 * The `/` naming helper: Named("field1", Int8ul) is construct's
 * `"field1" / Int8ul`.
 * @param {string} name
 * @param {Construct} subcon
 * @returns {Renamed}
 */
export function Named(name, subcon) {
  return new Renamed(subcon, name);
}

/**
 * construct.Struct: parses its subconstructs in order into a Container.
 * Unnamed members are parsed but not stored, exactly like construct.
 */
export class Struct extends Construct {
  /**
   * @param {...Construct} subcons
   */
  constructor(...subcons) {
    super();
    this.subcons = subcons.flat();
  }

  /**
   * @param {Buffer} buffer
   * @param {number} offset
   * @param {Record<string, unknown>} context
   * @returns {[Container, number]}
   */
  _parse(buffer, offset, context) {
    const container = new Container();
    let position = offset;
    for (const subcon of this.subcons) {
      const [value, next] = subcon._parse(buffer, position, container);
      position = next;
      if (subcon.name) container.set(subcon.name, value);
    }
    return [container, position];
  }

  /**
   * @param {Container|Record<string, unknown>} obj
   * @param {Record<string, unknown>} [context]
   * @returns {Buffer}
   */
  build(obj, context = {}) {
    const chunks = [];
    for (const subcon of this.subcons) {
      const value = subcon.name ? obj[subcon.name] : undefined;
      chunks.push(subcon.build(value, context));
    }
    return Buffer.concat(chunks);
  }

  sizeof() {
    return this.subcons.reduce((total, subcon) => total + subcon.sizeof(), 0);
  }

  toString() {
    return `Struct(${this.subcons.map((s) => s.name ?? '<unnamed>').join(', ')})`;
  }
}

export default { Construct, Subconstruct, Renamed, Struct, Named };

/**
 * Emulates construct's fixed-size number formats (construct.Int8ul and its
 * siblings). Naming follows construct: Int<bits><u|s><l|b>, i.e. bit width,
 * unsigned/signed, little/big endian.
 *
 * All byte access goes through node:buffer's Buffer read/write helpers.
 */

import { Buffer } from 'node:buffer';
import { StreamError } from '../errors.mjs';
import { Construct } from './core.mjs';

/**
 * A fixed-size scalar format: construct's FormatField.
 */
export class FormatField extends Construct {
  /**
   * @param {string} formatName construct's name for this format, e.g. "Int8ul"
   * @param {number} size width in bytes
   * @param {(buffer: Buffer, offset: number) => number|bigint} reader
   * @param {(buffer: Buffer, offset: number, value: number|bigint) => void} writer
   */
  constructor(formatName, size, reader, writer) {
    super();
    this.formatName = formatName;
    this.size = size;
    this.reader = reader;
    this.writer = writer;
  }

  /**
   * @param {Buffer} buffer
   * @param {number} offset
   * @returns {[number|bigint, number]}
   */
  _parse(buffer, offset) {
    if (offset + this.size > buffer.length) {
      throw new StreamError(
        `stream read less than specified amount, expected ${this.size}, ` +
        `found ${Math.max(0, buffer.length - offset)}`,
      );
    }
    return [this.reader(buffer, offset), offset + this.size];
  }

  /**
   * @param {number|bigint} value
   * @returns {Buffer}
   */
  build(value) {
    const buffer = Buffer.alloc(this.size);
    this.writer(buffer, 0, value);
    return buffer;
  }

  /** @returns {number} */
  sizeof() {
    return this.size;
  }

  toString() {
    return this.formatName;
  }
}

/**
 * Build a FormatField from Buffer accessor method names.
 * @param {string} formatName
 * @param {number} size
 * @param {string} readMethod
 * @param {string} writeMethod
 * @returns {FormatField}
 */
function field(formatName, size, readMethod, writeMethod) {
  return new FormatField(
    formatName,
    size,
    (buffer, offset) => buffer[readMethod](offset),
    (buffer, offset, value) => {
      buffer[writeMethod](value, offset);
    },
  );
}

/* 8-bit: endianness is a no-op but construct defines all four spellings. */
export const Int8ub = field('Int8ub', 1, 'readUInt8', 'writeUInt8');
export const Int8ul = field('Int8ul', 1, 'readUInt8', 'writeUInt8');
export const Int8sb = field('Int8sb', 1, 'readInt8', 'writeInt8');
export const Int8sl = field('Int8sl', 1, 'readInt8', 'writeInt8');

/* 16-bit */
export const Int16ub = field('Int16ub', 2, 'readUInt16BE', 'writeUInt16BE');
export const Int16ul = field('Int16ul', 2, 'readUInt16LE', 'writeUInt16LE');
export const Int16sb = field('Int16sb', 2, 'readInt16BE', 'writeInt16BE');
export const Int16sl = field('Int16sl', 2, 'readInt16LE', 'writeInt16LE');

/* 24-bit: Buffer supports arbitrary byte widths through readUIntBE/LE. */
export const Int24ub = new FormatField(
  'Int24ub', 3,
  (buffer, offset) => buffer.readUIntBE(offset, 3),
  (buffer, offset, value) => buffer.writeUIntBE(Number(value), offset, 3),
);
export const Int24ul = new FormatField(
  'Int24ul', 3,
  (buffer, offset) => buffer.readUIntLE(offset, 3),
  (buffer, offset, value) => buffer.writeUIntLE(Number(value), offset, 3),
);
export const Int24sb = new FormatField(
  'Int24sb', 3,
  (buffer, offset) => buffer.readIntBE(offset, 3),
  (buffer, offset, value) => buffer.writeIntBE(Number(value), offset, 3),
);
export const Int24sl = new FormatField(
  'Int24sl', 3,
  (buffer, offset) => buffer.readIntLE(offset, 3),
  (buffer, offset, value) => buffer.writeIntLE(Number(value), offset, 3),
);

/* 32-bit */
export const Int32ub = field('Int32ub', 4, 'readUInt32BE', 'writeUInt32BE');
export const Int32ul = field('Int32ul', 4, 'readUInt32LE', 'writeUInt32LE');
export const Int32sb = field('Int32sb', 4, 'readInt32BE', 'writeInt32BE');
export const Int32sl = field('Int32sl', 4, 'readInt32LE', 'writeInt32LE');

/* 64-bit: values are BigInt, matching Python's unbounded ints. */
export const Int64ub = field('Int64ub', 8, 'readBigUInt64BE', 'writeBigUInt64BE');
export const Int64ul = field('Int64ul', 8, 'readBigUInt64LE', 'writeBigUInt64LE');
export const Int64sb = field('Int64sb', 8, 'readBigInt64BE', 'writeBigInt64BE');
export const Int64sl = field('Int64sl', 8, 'readBigInt64LE', 'writeBigInt64LE');

/* IEEE floats */
export const Float32b = field('Float32b', 4, 'readFloatBE', 'writeFloatBE');
export const Float32l = field('Float32l', 4, 'readFloatLE', 'writeFloatLE');
export const Float64b = field('Float64b', 8, 'readDoubleBE', 'writeDoubleBE');
export const Float64l = field('Float64l', 8, 'readDoubleLE', 'writeDoubleLE');

/* construct's convenience aliases (big-endian "network" defaults). */
export const Byte = Int8ub;
export const Short = Int16ub;
export const Int = Int32ub;
export const Long = Int64ub;
export const Single = Float32b;
export const Double = Float64b;

export default {
  FormatField,
  Int8ub, Int8ul, Int8sb, Int8sl,
  Int16ub, Int16ul, Int16sb, Int16sl,
  Int24ub, Int24ul, Int24sb, Int24sl,
  Int32ub, Int32ul, Int32sb, Int32sl,
  Int64ub, Int64ul, Int64sb, Int64sl,
  Float32b, Float32l, Float64b, Float64l,
