#!/usr/bin/env node
/**
 * Node.js ESM port of test4.py.
 *
 * The original program:
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=int, required=True)
 *   parser.add_argument('--b', type=int, required=True)
 *   args = parser.parse_args()
 *   struct_format = construct.Struct("field1" / construct.Int8ul,
 *                                    "field2" / construct.Int8ul)
 *   data = bytes([args.a, args.b])
 *   result = struct_format.parse(data)
 *   print(result)
 *
 * Exit codes match the reference build: 0 on success and for -h/--help,
 * 1 when bytes() rejects an out-of-range value, 2 for any argparse error.
 */

import process from 'node:process';

import { ArgumentParser } from './lib/argparse/index.mjs';
import * as construct from './lib/construct/index.mjs';
import { ArgumentParserExit, PyException } from './lib/errors.mjs';
import { pythonBytes } from './lib/python/bytes.mjs';
import { pythonInt } from './lib/python/int.mjs';
import {
  reportUnhandledException,
  shutdownReportForStreamError,
} from './lib/python/traceback.mjs';

/**
 * Program name used in every usage line and "<prog>: error: ..." line.
 *
 * CPython derives argparse's `prog` from os.path.basename(sys.argv[0]); for the
 * frozen reference build that basename is "test4_executable". It is pinned here
 * so the usage and error text of this port lines up byte-for-byte with the
 * reference, instead of following the .mjs file name.
 */
export const PROG = 'test4_executable';

/** Python's print(): write the text plus a single LF, never CRLF. */
function print(text) {
  process.stdout.write(`${text}\n`);
}

/**
 * 1:1 translation of test4.py's main().
 */
export function main() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--a'], { type: pythonInt, required: true });
  parser.addArgument(['--b'], { type: pythonInt, required: true });
  const args = parser.parseArgs();

  const structFormat = new construct.Struct(
    construct.Named('field1', construct.Int8ul), // first field
    construct.Named('field2', construct.Int8ul), // second field
  );
  const data = pythonBytes([args.a, args.b]);
  const result = structFormat.parse(data);
  print(String(result));
}

/**
 * Reproduce CPython's behaviour when writing or flushing stdout fails: report
 * the error on stderr and still exit 0.
 */
function installStdoutFailureReporting() {
  process.stdout.on('error', (error) => {
    const report = shutdownReportForStreamError(error);
    if (report === null) return;
    try {
      process.stderr.write(report);
    } catch {
      // stderr is gone too; nothing else can be reported.
    }
    process.exitCode = 0;
  });
}

/**
 * `if __name__ == "__main__": main()`, plus the interpreter-level handling of
 * whatever escapes main().
 */
function run() {
  installStdoutFailureReporting();
  try {
    main();
  } catch (error) {
    if (error instanceof ArgumentParserExit) {
      // SystemExit raised by ArgumentParser.error()/exit(); text already sent.
      process.exitCode = error.status;
      return;
    }
    if (error instanceof PyException) {
      // Unhandled Python exception: PyInstaller-style traceback, exit code 1.
      reportUnhandledException(error);
      process.exitCode = 1;
      return;
    }
    throw error;
  }
}

run();

// Randomised differential fuzzer.
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test4_executable';
const norm = (s) => s.replace(/PYI-\d+/g, 'PYI-N');
function run(cmd, args, argv) {
  const r = spawnSync(cmd, [...args, ...argv], { encoding: 'buffer' });
  return { out: r.stdout.toString('binary'), err: norm(r.stderr.toString('binary')), rc: r.status };
}

const OPTS = ['--a', '--b', '-h', '--help', '--h', '--he', '--c', '--', '-', '--=',
  '--=5', '-hx', '-x', '--a=', '--b=', '--A', '--ab', '---a', '--1', '@f', '',
  '-1', '-1.5', '-0', '-x y', 'zzz', 'hello world', '--a=1=2', '-h=5', '--help=5'];
const VALS = ['0', '1', '91', '255', '256', '-1', '-0', '+5', ' 5 ', '5_0', '٩١', '１0',
  'foo', '', ' ', '0x10', '1e2', '-.5', '--', '-5', '1_', '_1', 'a\'b', 'a"b',
  '\t9', '5', ' 5', '﻿5', '᠎5', '​5', '²', '\u{1d7cf}',
  '\u{104a1}', 'é', '\n', '\x00', '\x7f5', 'a\nb', '9'.repeat(4301), '9'.repeat(4300)];
const POOL = [...OPTS, ...VALS];

const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
let fail = 0;
const N = Number(process.argv[2] ?? 400);
for (let i = 0; i < N; i += 1) {
  const len = 1 + Math.floor(Math.random() * 5);
  const argv = Array.from({ length: len }, () => (Math.random() < 0.55 ? pick(POOL) : pick(VALS)));
  // A NUL byte cannot be passed through execve, skip those.
  if (argv.some((a) => a.includes('\x00'))) continue;
  const expected = run(REF, [], argv);
  const actual = run(process.execPath, ['/output/test4.mjs'], argv);
  if (expected.out !== actual.out || expected.err !== actual.err || expected.rc !== actual.rc) {
    fail += 1;
    if (fail <= 20) {
      console.log(`MISMATCH argv=${JSON.stringify(argv)}`);
      console.log(`  rc ref=${expected.rc} port=${actual.rc}`);
      if (expected.out !== actual.out) {
        console.log(`  out ref=${JSON.stringify(expected.out).slice(0, 300)}`);
        console.log(`  out prt=${JSON.stringify(actual.out).slice(0, 300)}`);
      }
      if (expected.err !== actual.err) {
        console.log(`  err ref=${JSON.stringify(expected.err).slice(0, 300)}`);
        console.log(`  err prt=${JSON.stringify(actual.err).slice(0, 300)}`);
      }
    }
  }
}
console.log(`fuzz cases=${N} fail=${fail}`);
